command:example.dev:code:
Get-SHSecret -FilterCriteria @(
    @{ Field = 'vendorType'; Operator = 'EQ'; Value = 'AWS' }
    @{ Field = 'onboardData.status'; Operator = 'EQ'; Value = 'CANDIDATE' }
)

Get-SHSecretStore -FilterCriteria @(
    @{ Field = 'type'; Operator = 'EQ'; Value = 'AWS_ASM' }
    @{ Field = 'state'; Operator = 'EQ'; Value = 'ENABLED' }
)

New-SHSecretStore -type AWS_ASM -name 'Account alias - us-east-1' -data @{
    accountAlias = 'my-account-alias'
    accountId    = '123456789012'
    regionId     = 'us-east-1'
    roleName     = 'Secrets-Hub-IAM-Role'
}

New-SHSecretStore -type AZURE_AKV -name 'My Key Vault' -description 'Azure Key Vault for dev-team' -data @{
    appClientDirectoryId = 'c389961d-a0cd-46ab-9f69-877f756a59c1'
    appClientId          = 'c389961d-a0cd-46ab-9f69-877f756a59c1'
    azureVaultUrl        = 'https://example.vault.azure.net'
    connectionConfig     = @{ connectionType = 'PUBLIC' }
}

Publish-SHSecret -sourceSecretStoreType AWS_ASM -targetSecretStoreType PAM_PCLOUD `
    -secretId secret-a94a8fe5-ccb1-9ba6-1c4c-0873d391e987982fbbd3 `
    -secretValueType PLAINTEXT -safeName my-safe -pamAccount @{
        name                       = 'accountName'
        platformId                 = 'WinServerLocal'
        automaticManagementEnabled = $true
        properties                 = @{
            username = @{ type = 'VALUE'; value = 'example username' }
            address  = @{ type = 'VALUE'; value = 'example address' }
        }
    }

Publish-SHSecret -sourceSecretStoreType AZURE_AKV -targetSecretStoreType PAM_PCLOUD `
    -secretId $secretId -secretValueType JSON -safeName my-safe -pamAccount @{
        name       = 'accountName'
        platformId = 'WinServerLocal'
        properties = @{
            username = @{ type = 'KEY_REF'; keyRef = 'username' }
            password = @{ type = 'KEY_REF'; keyRef = 'password' }
        }
    }
